[{"order":1,"type":"heading","text":"Traversing the DOM and Assertions (Chai, expect, should) in Cypress"},{"order":2,"type":"paragraph","text":"Mastering DOM traversal and assertions is fundamental for writing robust end-to-end tests in Cypress. Cypress bundles Chai and Chai-jQuery, providing expressive assertion styles that integrate seamlessly with its command queue."},{"order":3,"type":"subheading","text":"Traversing DOM Elements"},{"order":4,"type":"paragraph","text":"Cypress provides a rich set of querying and traversal commands to navigate through the Document Object Model efficiently starting from an initial element."},{"order":5,"type":"bullet_point","text":".children([selector]): Gets the children of each DOM element within a set of DOM elements."},{"order":6,"type":"bullet_point","text":".parent([selector]) / .parents([selector]): Gets the parent or ancestor elements of a DOM element."},{"order":7,"type":"bullet_point","text":".find(selector): Gets the descendant elements of a specific DOM element matching a selector."},{"order":8,"type":"bullet_point","text":".first() / .last() / .eq(index): Selects a specific element from a collection based on its position."},{"order":9,"type":"code","text":"cy.get('.nav-list').find('li').first().should('have.class', 'active');"},{"order":10,"type":"subheading","text":"Understanding Assertions: Implicit vs. Explicit"},{"order":11,"type":"paragraph","text":"Cypress supports both implicit assertions (via .should() and .and()) and explicit assertions (via Chai's expect and should interfaces)."},{"order":12,"type":"bullet_point","text":"Implicit Assertions: Automatically retried until the assertion passes or the timeout is reached."},{"order":13,"type":"bullet_point","text":"Explicit Assertions: Useful when you need to parse or manipulate values before asserting."},{"order":14,"type":"subheading","text":"Using Chai's 'expect' Syntax"},{"order":15,"type":"paragraph","text":"The expect interface is typically used inside a .then() block when dealing with yielded subjects explicitly."},{"order":16,"type":"code","text":"cy.get('.user-profile').invoke('text').then((text) => {
  expect(text.trim()).to.eq('John Doe');
});"},{"order":17,"type":"subheading","text":"Using Chai's 'should' Syntax"},{"order":18,"type":"paragraph","text":"The BDD should style extends Object.prototype to provide a chainable getter-based assertion approach."},{"order":19,"type":"code","text":"cy.get('.submit-btn').should(($btn) => {
  expect($btn).to.have.class('enabled');
  expect($btn).to.not.be.disabled;
});"},{"order":20,"type":"subheading","text":"Common Assertion Patterns"},{"order":21,"type":"bullet_point","text":"Existence: cy.get('#loading').should('not.exist');"},{"order":22,"type":"bullet_point","text":"Visibility: cy.get('.modal').should('be.visible');"},{"order":23,"type":"bullet_point","text":"Value: cy.get('input[name="email"]').should('have.value', 'test@example.com');"},{"order":24,"type":"bullet_point","text":"CSS Properties: cy.get('.alert').should('have.css', 'background-color', 'rgb(255, 0, 0)');"}]
